import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Creating Codeunits","description":"","frontmatter":{},"headers":[],"relativePath":"codeunits/creating-codeunits.md","filePath":"codeunits/creating-codeunits.md"}`),a={name:`codeunits/creating-codeunits.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="creating-codeunits" tabindex="-1">Creating Codeunits <a class="header-anchor" href="#creating-codeunits" aria-label="Permalink to “Creating Codeunits”">​</a></h1><h2 id="creating-a-codeunit-in-vs-code" tabindex="-1">Creating a codeunit in VS Code <a class="header-anchor" href="#creating-a-codeunit-in-vs-code" aria-label="Permalink to “Creating a codeunit in VS Code”">​</a></h2><p>In your existing AL project:</p><ol><li>Create a new <code>.al</code> file, for example, <code>CustomerManager.Codeunit.al</code>.</li><li>Type <code>tcodeunit</code> and press Enter. VS Code generates a basic codeunit structure.</li><li>Give it a unique object ID and a meaningful name.</li></ol><p>A basic codeunit looks like this:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 CustomerManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        </span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s understand the structure:</p><ul><li><code>codeunit</code>: Declares the object type.</li><li><code>50100</code>: The object&#39;s unique ID within the relevant object ID range.</li><li><code>CustomerManager</code>: The object&#39;s name.</li><li><code>OnRun()</code>: A trigger that executes when the codeunit itself is run.</li></ul><p><strong>Important:</strong> A codeunit doesn&#39;t have to contain an <code>OnRun()</code> trigger. You can create a codeunit containing only procedures.</p><h2 id="adding-procedures-to-a-codeunit" tabindex="-1">Adding procedures to a codeunit <a class="header-anchor" href="#adding-procedures-to-a-codeunit" aria-label="Permalink to “Adding procedures to a codeunit”">​</a></h2><p>Remember procedures from our earlier lessons?</p><p>A codeunit can contain multiple procedures. These procedures hold the actual business logic that other objects can reuse.</p><p>Let&#39;s create a procedure that retrieves a customer using their customer number.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50100 CustomerManager</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    procedure DisplayCustomer(CustomerNo: Code[20])</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        CustomerRec: Record Customer;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if CustomerRec.Get(CustomerNo) then</span></span>
<span class="line"><span>            Message(&#39;Customer: %1&#39;, CustomerRec.Name)</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;Customer not found.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Let&#39;s break this down:</p><p><strong>1. Procedure declaration</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>procedure DisplayCustomer(CustomerNo: Code[20])</span></span></code></pre></div><ul><li><code>DisplayCustomer</code> is the procedure name.</li><li><code>CustomerNo</code> is a parameter.</li><li><code>Code[20]</code> is the parameter&#39;s data type.</li></ul><p>The procedure expects a customer number when called.</p><p><strong>2. Record variable</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    CustomerRec: Record Customer;</span></span></code></pre></div><p>We&#39;re using the <code>Record</code> data type we learned earlier to access the Customer table.</p><p><strong>3. Retrieving the customer</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if CustomerRec.Get(CustomerNo) then</span></span></code></pre></div><p>Remember <code>Get()</code>? It retrieves a record using its primary key.</p><p>If the customer exists, we display their name. Otherwise, we display a message indicating that the customer wasn&#39;t found.</p><p>Notice that we&#39;re reusing concepts we&#39;ve already covered: record variables, <code>Get()</code>, conditional statements and <code>Message()</code>.</p><h2 id="calling-a-codeunit-from-another-object" tabindex="-1">Calling a codeunit from another object <a class="header-anchor" href="#calling-a-codeunit-from-another-object" aria-label="Permalink to “Calling a codeunit from another object”">​</a></h2><p>Creating a codeunit is only half the job. We also need to understand how other objects use it.</p><p>Suppose we want to call our <code>DisplayCustomer()</code> procedure from the Customer Card page.</p><p>We can create a page extension:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50101 CustomerCardExt extends &quot;Customer Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    actions</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        addlast(Processing)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            action(ShowCustomerDetails)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                Caption = &#39;Show Customer Details&#39;;</span></span>
<span class="line"><span>                ApplicationArea = All;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                trigger OnAction()</span></span>
<span class="line"><span>                var</span></span>
<span class="line"><span>                    CustomerManager: Codeunit CustomerManager;</span></span>
<span class="line"><span>                begin</span></span>
<span class="line"><span>                    CustomerManager.DisplayCustomer(Rec.&quot;No.&quot;);</span></span>
<span class="line"><span>                end;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>There are two important things here.</p><p><strong>First, declaring a codeunit variable:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CustomerManager: Codeunit CustomerManager;</span></span></code></pre></div><p>Just as we declare record variables using <code>Record</code>, we declare codeunit variables using <code>Codeunit</code>.</p><p><strong>Second, calling a procedure:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CustomerManager.DisplayCustomer(Rec.&quot;No.&quot;);</span></span></code></pre></div><p>We call the procedure using the codeunit variable followed by a dot and the procedure name.</p><p><code>Rec.&quot;No.&quot;</code> refers to the customer number of the currently displayed customer on the Customer Card page.</p><p>When the user clicks <strong>Show Customer Details</strong>, the page calls our codeunit, which retrieves the customer and displays their name.</p><p>This is one of the main reasons codeunits are useful: the page handles the user interaction, while the codeunit handles the business logic.</p><h2 id="understanding-the-onrun-trigger" tabindex="-1">Understanding the OnRun() trigger <a class="header-anchor" href="#understanding-the-onrun-trigger" aria-label="Permalink to “Understanding the OnRun() trigger”">​</a></h2><p>We briefly introduced <code>OnRun()</code> earlier. Now let&#39;s distinguish it from procedures.</p><p>Consider this codeunit:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50102 CustomerProcessor</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnRun()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Customer Processor is running.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>OnRun()</code> trigger executes when the codeunit itself is run.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Codeunit.Run(Codeunit::CustomerProcessor);</span></span></code></pre></div><p>However, when you declare a codeunit variable and call one of its procedures:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CustomerManager.DisplayCustomer(&#39;10000&#39;);</span></span></code></pre></div><p><strong>The <code>OnRun()</code> trigger does not execute automatically.</strong> You&#39;re calling the procedure directly.</p><p>This distinction is important.</p><table tabindex="0"><thead><tr><th>How you invoke the codeunit</th><th>What executes</th></tr></thead><tbody><tr><td><code>Codeunit.Run(Codeunit::CustomerProcessor)</code></td><td><code>OnRun()</code></td></tr><tr><td><code>CustomerManager.DisplayCustomer(&#39;10000&#39;)</code></td><td><code>DisplayCustomer()</code></td></tr></tbody></table><p>You don&#39;t need to use <code>OnRun()</code> for every codeunit. In fact, many codeunits primarily expose reusable procedures.</p><h3 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further reading”">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-codeunit-object" target="_blank" rel="noreferrer">Microsoft Learn: Codeunit Object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/triggers-auto/codeunit/devenv-onrun-codeunit-trigger" target="_blank" rel="noreferrer">Microsoft Learn: OnRun Codeunit Trigger</a></li><li><a href="https://learn.microsoft.com/en-us/training/modules/work-with-codeunits/" target="_blank" rel="noreferrer">Microsoft Learn: Work with Codeunits</a></li></ul>`,57)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};